<?php
session_start();if(empty($_SESSION['utilisateur_id'])){header('Location: ../connexion.php');exit;}$roles=$_SESSION['utilisateur_roles']??[];if(!is_array($roles)||!in_array('administrateur',$roles,true)){http_response_code(403);exit('Accès refusé.');}if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: paiements.php');exit;}
$token=$_POST['csrf_token']??'';if(empty($_SESSION['csrf_paiement_admin'])||!is_string($token)||!hash_equals($_SESSION['csrf_paiement_admin'],$token)){http_response_code(403);exit('Formulaire expiré.');}$idPaiement=filter_input(INPUT_POST,'id_paiement',FILTER_VALIDATE_INT);$action=$_POST['action']??'';$commentaire=trim((string)($_POST['commentaire']??''));if(!$idPaiement||!in_array($action,['confirmer','refuser'],true))exit('Informations invalides.');if($action==='refuser'&&$commentaire==='')exit('Indiquez un motif de refus.');
require_once __DIR__.'/../classes/Database.php';$pdo=(new Database())->getConnection();$admin=(int)$_SESSION['utilisateur_id'];
try{$pdo->beginTransaction();$q=$pdo->prepare("SELECT pa.id_paiement,pa.id_abonnement,pa.statut_paiement,a.id_proprietaire FROM paiement_abonnement pa INNER JOIN abonnement a ON a.id_abonnement=pa.id_abonnement WHERE pa.id_paiement=? FOR UPDATE");$q->execute([$idPaiement]);$p=$q->fetch(PDO::FETCH_ASSOC);if(!$p)throw new RuntimeException('Paiement introuvable.');if($p['statut_paiement']!=='en_attente')throw new RuntimeException('Ce paiement a déjà été traité.');
if($action==='confirmer'){$q=$pdo->prepare("SELECT COUNT(*) FROM abonnement WHERE id_proprietaire=? AND statut='actif' AND date_fin>CURRENT_TIMESTAMP AND id_abonnement<>?");$q->execute([(int)$p['id_proprietaire'],(int)$p['id_abonnement']]);if((int)$q->fetchColumn()>0)throw new RuntimeException('Le propriétaire possède déjà un abonnement actif.');$q=$pdo->prepare("UPDATE paiement_abonnement SET statut_paiement='confirme',valide_par=?,date_validation=CURRENT_TIMESTAMP,commentaire_validation=? WHERE id_paiement=? AND statut_paiement='en_attente'");$q->execute([$admin,$commentaire!==''?$commentaire:null,$idPaiement]);$q=$pdo->prepare("UPDATE abonnement SET statut='actif',date_activation=CURRENT_TIMESTAMP,date_debut=CURRENT_TIMESTAMP,date_fin=DATE_ADD(CURRENT_TIMESTAMP,INTERVAL 30 DAY),quota_publications=30 WHERE id_abonnement=? AND statut='en_attente'");$q->execute([(int)$p['id_abonnement']]);if($q->rowCount()!==1)throw new RuntimeException('Activation de l’abonnement impossible.');}else{$q=$pdo->prepare("UPDATE paiement_abonnement SET statut_paiement='refuse',valide_par=?,date_validation=CURRENT_TIMESTAMP,commentaire_validation=? WHERE id_paiement=? AND statut_paiement='en_attente'");$q->execute([$admin,$commentaire,$idPaiement]);$q=$pdo->prepare("UPDATE abonnement SET statut='refuse' WHERE id_abonnement=? AND statut='en_attente'");$q->execute([(int)$p['id_abonnement']]);}
$pdo->commit();$_SESSION['csrf_paiement_admin']=bin2hex(random_bytes(32));header('Location: paiements.php?resultat=succes');exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Paiement MIGON: '.$e->getMessage());http_response_code(400);exit('Erreur : '.$e->getMessage());}
